// ---- code/emi.view.v8ui.js
// [v8ui] piano roll for the engine's current score, inside emi.view. Patches
// load patchers/emi.view.bundle.js.
//
// Notes are colored by source chorale for composed pieces (by voice for a
// single chorale); thin lines mark bars, bright lines mark seams, where the
// source changes (orange where voices were moved by octaves to join), and
// small triangles along the top mark cadences (fermatas). A lane along the
// bottom shows each beat's SPEAC label (M6): S statement, P preparation,
// E extension, A antecedent, C consequent. Gold bands mark signature blocks
// (M7), named by their signature. Small carets above the lane mark parallel
// fifths and octaves (M8): grey for Bach's own, red for new ones. With the
// mouse over a beat, a box at the top shows where it came from (M8: the
// provenance view). Dragging across the roll selects whole beats for
// Emily to rate (M9): a blue band, sent to the engine as "select <from>
// <to>" (ticks) while dragging; a click clears it ("select"). Bars are
// numbered along the top and each C is labelled on the left, where there is
// room. The same script draws the small roll in the panels and the large
// one in the pop-up window (emi.window); lettering grows with the size.
// The engine sends one score as:
//   clear <endTick> <lowPitch> <highPitch> <barTicks> [startTick] [beatTicks]
//                                        (the ticks shown; a stream shows its last phrases)
//   note <on> <dur> <pitch> <color>      (one per note)
//   seam <tick> [level]                  (one per seam; level 1: octave moves)
//   cadence <tick>                       (one per fermata)
//   speac <tick> <label>                 (one per beat)
//   signature <start> <end> <name...>    (one per signature block, e.g. "soprano 3-2-1")
//   parallel <tick> <new>                (one per parallel 5th/8ve; new: 1, Bach's own: 0)
//   source <tick> <text...>              (one per beat: where it came from)
//   selection <from> <to>                (the beats selected, kept when a stream redraws)
//   variant <tick> <names...>            (M10: a beat Emily varied: a purple dot over it)
//   done                                 (draw it)
// and, at any time:
//   highlight <from> <to> | highlight    (the selection, made in the other roll; or none)
//   playhead <step>                      (where the player is, in 16ths from tick 0; -1: hidden)

autowatch = 1;
inlets = 1;
outlets = 1;

mgraphics.init();
mgraphics.relative_coords = 0;
mgraphics.autofill = 0;

// Twelve colors that stay apart on a dark background; they repeat after 12.
// SPEAC lane colors: tension rising (P, A) warm, resolving (C) cool.
const SPEAC_COLORS = { S: [0.55, 0.6, 0.7], P: [0.5, 0.8, 0.45], E: [0.35, 0.35, 0.38], A: [0.95, 0.5, 0.3], C: [0.4, 0.65, 0.95] };
const NOTE_NAMES = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];
const GOLD = [1, 0.82, 0.3];

const PALETTE = [
  [0.95, 0.55, 0.35], [0.35, 0.7, 0.95], [0.6, 0.85, 0.4], [0.95, 0.8, 0.3],
  [0.75, 0.5, 0.95], [0.3, 0.85, 0.75], [0.95, 0.45, 0.6], [0.55, 0.6, 0.95],
  [0.85, 0.65, 0.45], [0.45, 0.9, 0.55], [0.9, 0.4, 0.4], [0.7, 0.75, 0.8],
];

let shown = null; // the score being drawn
let incoming = null; // the score being received
let hover = null; // the beat under the mouse: an index into shown.sources
let selected = null; // [from, to]: the ticks selected (whole beats)
let playTick = null; // where the player is (a tick), or null when it isn't playing
let dragFrom = null; // the tick of the beat where a drag started

function clear(endTick, low, high, barTicks, startTick, beatTicks) {
  incoming = { selected: null, variants: [], start: startTick || 0, end: endTick, low, high, barTicks, beatTicks: beatTicks || barTicks / 4, notes: [], seams: [], cadences: [], labels: [], signatures: [], parallels: [], sources: [] };
}

function note(on, dur, pitch, color) {
  if (incoming) incoming.notes.push([on, dur, pitch, color]);
}

function seam(tick, level) {
  if (incoming) incoming.seams.push([tick, level || 0]);
}

function cadence(tick) {
  if (incoming) incoming.cadences.push(tick);
}

function speac(tick, label) {
  if (incoming) incoming.labels.push([tick, String(label)]);
}

function signature(start, end, ...name) {
  if (incoming) incoming.signatures.push([start, end, name.join(" ")]);
}

function parallel(tick, fresh) {
  if (incoming) incoming.parallels.push([tick, fresh ? 1 : 0]);
}

function source(tick, ...text) {
  if (incoming) incoming.sources.push([tick, text.join(" ")]);
}

function selection(from, to) {
  if (incoming) incoming.selected = [from, to];
}

function variant(tick, ...names) {
  if (incoming) incoming.variants.push([tick, names.join(" ")]);
}

// The playhead: a line where the player is. Redrawn only when it moves by a
// pixel or more, so the roll isn't repainted needlessly.
function playhead(step) {
  const tick = step >= 0 && shown ? (step * beatOf(shown)) / 4 : null;
  if (tick === playTick) return;
  const [width] = size();
  const px = (t) => (t === null || !shown ? null : Math.round(((t - shown.start) / (shown.end - shown.start)) * width));
  const moved = px(tick) !== px(playTick);
  playTick = tick;
  if (moved) mgraphics.redraw();
}

function highlight(from, to) {
  selected = from !== undefined && to !== undefined && to > from ? [from, to] : null;
  mgraphics.redraw();
}

function done() {
  if (incoming) {
    shown = incoming;
    selected = incoming.selected;
  }
  incoming = null;
  hover = null;
  mgraphics.redraw();
}

// The provenance view: the beat under the mouse.
function onidle(x) {
  const found = sourceAt(x);
  if (found !== hover) {
    hover = found;
    mgraphics.redraw();
  }
}

function onidleout() {
  if (hover !== null) {
    hover = null;
    mgraphics.redraw();
  }
}

// A click starts a selection (and clears the one before); dragging extends
// it beat by beat.
function onclick(x) {
  onidle(x);
  if (selected) outlet(0, "select");
  selected = null;
  dragFrom = beatTickAt(x);
  mgraphics.redraw();
}

function ondrag(x, y, button) {
  if (!shown || dragFrom === null) return;
  const tick = beatTickAt(x);
  if (tick !== null && tick !== dragFrom) {
    const next = [Math.min(dragFrom, tick), Math.max(dragFrom, tick) + beatOf(shown)];
    if (!selected || next[0] !== selected[0] || next[1] !== selected[1]) {
      selected = next;
      outlet(0, "select", selected[0], selected[1]);
      mgraphics.redraw();
    }
  }
  if (!button) dragFrom = null;
}

// The start of the beat under x (within the ticks shown), or null.
function beatTickAt(px) {
  if (!shown) return null;
  const [width] = size();
  const beat = beatOf(shown);
  const tick = shown.start + (Math.max(0, Math.min(width - 1, px)) / width) * (shown.end - shown.start);
  return Math.floor(tick / beat) * beat;
}
beatTickAt.local = 1;

function sourceAt(px) {
  if (!shown || !shown.sources.length) return null;
  const [width] = size();
  const tick = shown.start + (px / width) * (shown.end - shown.start);
  for (let i = shown.sources.length - 1; i >= 0; i--) {
    const [at] = shown.sources[i];
    if (at <= tick && tick < at + beatOf(shown)) return i;
  }
  return null;
}
sourceAt.local = 1;

function beatOf(score) {
  return score.beatTicks || score.barTicks / 4;
}
beatOf.local = 1;

function onresize() {
  mgraphics.redraw();
}

function paint() {
  const [width, height] = size();
  const g = mgraphics;
  g.set_source_rgba(0.12, 0.12, 0.13, 1);
  g.rectangle(0, 0, width, height);
  g.fill();
  if (!shown || shown.end <= shown.start) {
    g.set_source_rgba(0.6, 0.6, 0.6, 1);
    g.select_font_face("Arial");
    g.set_font_size(11);
    g.move_to(8, 18);
    g.show_text("load a chorale or compose a piece");
    return;
  }

  // Lettering grows with the roll: the panels' roll is 169 px high, the
  // window's about 430.
  const big = height >= 300;
  const lane = Math.max(12, Math.round(height / 20));
  const rollHeight = shown.labels.length ? height - lane : height;
  const rows = shown.high - shown.low + 3; // one empty row above and below
  const rowHeight = rollHeight / rows;
  const x = (tick) => ((tick - shown.start) / (shown.end - shown.start)) * width;
  const y = (pitch) => (shown.high + 1 - pitch) * rowHeight;

  g.set_line_width(1);
  g.set_source_rgba(1, 1, 1, 0.08);
  for (let t = Math.ceil(shown.start / shown.barTicks) * shown.barTicks; t <= shown.end; t += shown.barTicks) {
    g.move_to(Math.round(x(t)) + 0.5, 0);
    g.line_to(Math.round(x(t)) + 0.5, rollHeight);
  }
  g.stroke();

  // Each C: a faint line and its name on the left (C4 is middle C), where
  // rows are tall enough to read.
  if (rowHeight >= 5) {
    g.select_font_face("Arial");
    g.set_font_size(big ? 11 : 8);
    for (let pitch = shown.low - 1; pitch <= shown.high + 1; pitch++) {
      if (pitch % 12 !== 0) continue;
      g.set_source_rgba(1, 1, 1, 0.06);
      g.rectangle(0, y(pitch) + rowHeight - 1, width, 1);
      g.fill();
      g.set_source_rgba(1, 1, 1, 0.35);
      g.move_to(2, y(pitch) + rowHeight - 2);
      g.show_text(NOTE_NAMES[pitch % 12] + (Math.floor(pitch / 12) - 1));
    }
  }

  // Bar numbers along the top, where bars are wide enough.
  if (x(shown.barTicks) - x(0) >= 18) {
    g.select_font_face("Arial");
    g.set_font_size(big ? 12 : 8);
    g.set_source_rgba(1, 1, 1, 0.45);
    for (let t = Math.ceil(shown.start / shown.barTicks) * shown.barTicks; t < shown.end; t += shown.barTicks) {
      g.move_to(Math.round(x(t)) + 3, big ? 13 : 8);
      g.show_text(String(Math.floor(t / shown.barTicks) + 1));
    }
  }

  // Signature blocks: a gold band behind the notes, its name at the top
  // ("soprano 3-2-1", or "S 3-2-1" where the band is narrow).
  g.select_font_face("Arial");
  g.set_font_size(big ? 12 : 9);
  for (const [start, end, name] of shown.signatures) {
    const left = x(start);
    const w = x(end) - left;
    g.set_source_rgba(GOLD[0], GOLD[1], GOLD[2], 0.13);
    g.rectangle(left, 0, w, rollHeight);
    g.fill();
    g.set_source_rgba(GOLD[0], GOLD[1], GOLD[2], 0.8);
    g.rectangle(left, rollHeight - 2, w, 2);
    g.fill();
    const words = name.split(" ");
    const text = w >= 70 ? name : w >= 32 ? words[0].charAt(0).toUpperCase() + " " + words.slice(1).join(" ") : "";
    if (text) {
      g.move_to(left + 3, big ? 28 : 17);
      g.show_text(text);
    }
  }

  for (const [on, dur, pitch, color] of shown.notes) {
    const [r, gr, b] = PALETTE[((color % PALETTE.length) + PALETTE.length) % PALETTE.length];
    g.set_source_rgba(r, gr, b, 0.9);
    g.rectangle(x(on), y(pitch), Math.max(1, x(on + dur) - x(on) - 1), Math.max(1, rowHeight - 1));
    g.fill();
  }

  for (const level of [0, 1]) {
    if (level === 0) g.set_source_rgba(1, 1, 1, 0.35);
    else g.set_source_rgba(1, 0.6, 0.15, 0.9);
    for (const [tick, l] of shown.seams) {
      if (l !== level) continue;
      g.move_to(Math.round(x(tick)) + 0.5, 0);
      g.line_to(Math.round(x(tick)) + 0.5, rollHeight);
    }
    g.stroke();
  }

  // The SPEAC lane: a colored block per beat, with its letter when there's room.
  const beat = beatOf(shown);
  const beatWidth = x(beat) - x(0);
  g.select_font_face("Arial");
  const laneFont = big ? 13 : 9;
  g.set_font_size(laneFont);
  for (const [tick, label] of shown.labels) {
    const [r, gr, b] = SPEAC_COLORS[label] || SPEAC_COLORS.E;
    g.set_source_rgba(r, gr, b, 0.9);
    g.rectangle(x(tick), rollHeight + 1, Math.max(1, beatWidth - 1), lane - 2);
    g.fill();
    if (beatWidth >= 9) {
      g.set_source_rgba(0.08, 0.08, 0.09, 1);
      g.move_to(x(tick) + beatWidth / 2 - laneFont / 3, rollHeight + lane / 2 + laneFont / 3);
      g.show_text(label);
    }
  }

  // Parallel fifths and octaves: a caret pointing up from the bottom of the roll.
  for (const [tick, fresh] of shown.parallels) {
    if (fresh) g.set_source_rgba(1, 0.25, 0.2, 0.95);
    else g.set_source_rgba(0.7, 0.7, 0.72, 0.8);
    const px = x(tick);
    g.move_to(px - 4, rollHeight - 1);
    g.line_to(px + 4, rollHeight - 1);
    g.line_to(px, rollHeight - 8);
    g.close_path();
    g.fill();
  }

  // Beats Emily varied (M10): a purple dot over each.
  for (const [tick] of shown.variants || []) {
    const r = big ? 5 : 3;
    g.set_source_rgba(0.75, 0.45, 1, 0.95);
    g.ellipse(x(tick) + beatWidth / 2 - r, (big ? 18 : 11) - r, 2 * r, 2 * r);
    g.fill();
  }

  // The beats selected for rating: a blue band over the roll and the lane.
  if (selected) {
    const left = x(Math.max(selected[0], shown.start));
    const right = x(Math.min(selected[1], shown.end));
    if (right > left) {
      g.set_source_rgba(0.35, 0.6, 1, 0.22);
      g.rectangle(left, 0, right - left, height);
      g.fill();
      g.set_source_rgba(0.45, 0.7, 1, 0.9);
      g.rectangle(left, 0, right - left, 2);
      g.fill();
    }
  }

  // The provenance view: the hovered beat lit up, and its source above.
  if (hover !== null && shown.sources[hover]) {
    const [tick, text] = shown.sources[hover];
    const left = x(tick);
    g.set_source_rgba(1, 1, 1, 0.12);
    g.rectangle(left, 0, x(tick + beatOf(shown)) - left, rollHeight);
    g.fill();
    g.select_font_face("Arial");
    const font = big ? 14 : 10;
    g.set_font_size(font);
    const boxWidth = Math.min(width - 4, text.length * font * 0.56 + 10);
    const boxLeft = Math.max(2, Math.min(left, width - boxWidth - 2));
    const top = big ? 34 : 8;
    g.set_source_rgba(0.05, 0.05, 0.06, 0.85);
    g.rectangle(boxLeft, top, boxWidth, font + 6);
    g.fill();
    g.set_source_rgba(1, 1, 1, 0.95);
    g.move_to(boxLeft + 5, top + font + 1);
    g.show_text(text);
  }

  // The playhead: a bright line where the player is, with a small marker on top.
  if (playTick !== null && playTick >= shown.start && playTick <= shown.end) {
    const px = Math.round(x(playTick)) + 0.5;
    g.set_source_rgba(1, 0.92, 0.55, 0.9);
    g.set_line_width(big ? 2 : 1.5);
    g.move_to(px, 0);
    g.line_to(px, rollHeight);
    g.stroke();
    g.move_to(px - 4, rollHeight);
    g.line_to(px + 4, rollHeight);
    g.line_to(px, rollHeight - 6);
    g.close_path();
    g.fill();
    g.set_line_width(1);
  }

  g.set_source_rgba(1, 1, 1, 0.85);
  for (const tick of shown.cadences) {
    const cx = x(tick);
    g.move_to(cx - 4, 0);
    g.line_to(cx + 4, 0);
    g.line_to(cx, 6);
    g.close_path();
    g.fill();
  }
}

function size() {
  if (mgraphics.size) return mgraphics.size;
  const rect = box.rect;
  return [rect[2] - rect[0], rect[3] - rect[1]];
}
size.local = 1;
